import { chromium } from '/var/tmp/avb-runs/avb-JTWtNZ/project/node_modules/playwright/index.mjs';
const b = await chromium.launch();
for (const [w,h] of [[1280,800],[390,844]]) {
  const p = await b.newPage({viewport:{width:w,height:h}});
  await p.goto('http://127.0.0.1:4173/contact.html');
  const base = await p.evaluate(() => {
    const dd = document.querySelectorAll('.info-list dd')[0];
    const r = dd.getBoundingClientRect();
    return {w: r.width, h: r.height, sw: document.documentElement.scrollWidth, ow: getComputedStyle(dd).overflowWrap, wb: getComputedStyle(dd).wordBreak, ws: getComputedStyle(dd).whiteSpace};
  });
  console.log(`viewport ${w}: default`, base);
  for (const css of ['overflow-wrap:anywhere','overflow-wrap:break-word','word-break:break-all','word-break:break-word','word-break:break-word;overflow-wrap:anywhere']) {
    const r = await p.evaluate((css) => {
      let s = document.getElementById('probe'); if(!s){s=document.createElement('style');s.id='probe';document.head.append(s);}
      s.textContent = `.info-list dd { ${css} }`;
      const dd = document.querySelectorAll('.info-list dd')[0];
      const rect = dd.getBoundingClientRect();
      return {css, w: rect.width, h: rect.height, sw: document.documentElement.scrollWidth};
    }, css);
    console.log(`viewport ${w}:`, r);
  }
  await p.close();
}
await b.close();
EOF
PORT=4173 node server.js > "$TMPDIR/server.log" 2>&1 &
sleep 1
node "$TMPDIR/probe.mjs"

